CREATE OR REPLACE FUNCTION calculate_sustainability_index(p_equipment_code character varying)
RETURNS numeric AS $$
DECLARE
    v_energy_efficiency numeric;
    v_power_source USER-DEFINED;  -- We need to check the actual type
    v_multiplier numeric;
BEGIN
    SELECT energyefficiencypercent, powersource
    INTO v_energy_efficiency, v_power_source
    FROM powerbattery
    WHERE pwrbatteqref = p_equipment_code;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    CASE v_power_source::text
        WHEN 'Solar' THEN v_multiplier := 1.5;
        WHEN 'Wind' THEN v_multiplier := 1.5;
        WHEN 'Hybrid' THEN v_multiplier := 1.2;
        WHEN 'Battery' THEN v_multiplier := 1.0;
        WHEN 'Diesel' THEN v_multiplier := 0.7;
        ELSE v_multiplier := 0;
    END CASE;

    RETURN ROUND(CAST(v_energy_efficiency * v_multiplier AS numeric), 2);
END;
$$ LANGUAGE plpgsql;

